import React, { useState } from "react";
import axios from "axios";
import { apiHandle } from "../../Config/ApiHandle/apiHandle";

const SearchByURL = ({ setFormData, colorTheme,setIsArticleInfoOpen }) => {
    const [url, setUrl] = useState("");
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState("");
    const [cancelToken] = useState(axios.CancelToken.source());

    // Fetch data from the API
    const fetchDataFromURL = async () => {
        setLoading(true);
        setError("");

        try {
            const response = await axios.post(
                "http://174.136.228.165:8000/extract",
                { url: url },
                {
                    timeout: 60000,
                    cancelToken: cancelToken.token // Cancel token attach karein
                }
            );

            const data = response.data;
            setIsArticleInfoOpen(true);
            // Fetch authors from the library (get-authors API)
            const authorsLibraryResponse = await apiHandle.get("get-authors");
            const authorsLibrary = authorsLibraryResponse?.data?.authors;

            // Split the authors string into an array of authors
            const authorsArray = data.authors
                ? data.authors.split(",").map((author) => {
                    const trimmedAuthorName = author.trim(); // Trim spaces for clean data

                    // Check if the author exists in the library
                    const matchedAuthor = authorsLibrary.find(
                        (libraryAuthor) =>
                            libraryAuthor.name.toLowerCase() === trimmedAuthorName.toLowerCase()
                    );

                    return {
                        name: trimmedAuthorName,
                        parent_id: matchedAuthor ? matchedAuthor.id : 1, // Use matched author's ID or default to 1
                    };
                })
                : []; // If no authors, default to an empty array

            // Function to clean HTML
            const sanitizeHTMLWithDOMParser = (html) => {
                const parser = new DOMParser();
                const doc = parser.parseFromString(html, "text/html");
                return doc.body.innerText || "";
            };

            const rawAbstract = data.abstract || "";
            const sanitizedAbstract = sanitizeHTMLWithDOMParser(rawAbstract);

            // Update `formData` with the fetched data
            setFormData({
                title: { name: data.title || "", status: "Unverified" },
                authors: authorsArray,
                year: { name: data.year ? parseInt(data.year, 10) : "", status: "Unverified" },
                country: [],
                ...(data.grantCountry && { 
                    grantCountry: { name: data.grantCountry, status: "Unverified" } 
                  }),
                researchCountry: [],
                pmid: { name: data.pmid || "", status: "Unverified" },
                doi: { name: data.doi || "", status: "Unverified" },
                abstract: { name: sanitizedAbstract, status: "Unverified" },
                publisher: { name: data.publisher || "", status: "Unverified" },
                journal: { name: data.journal || "", status: "Unverified" },
                journalURL: { name: data.journalURL || "", status: "Unverified" },
                volume: { name: data.Volume || "", status: "Unverified" },
                pages: { name: data.pages || "", status: "Unverified" },
                impactFactor: { name: data.impactFactor || "", status: "Unverified" },
                HIndex: { name: data.HIndex || "", status: "Unverified" },
                sciMAGO: { name: data.sciMAGO || "", status: "Unverified" },
                pdf_url: [],
            });
        } catch (err) {
            setError("Failed to fetch data. Please check the URL and try again.");
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="mb-6">
            <label className="block text-gray-700 mb-2">Search by URL</label>
            <div className="flex items-center">
                <input
                    type="text"
                    className="border px-4 py-2 rounded w-full mr-4"
                    placeholder="Search by URL"
                    value={url}
                    onChange={(e) => setUrl(e.target.value)}
                />
                <button
                    type="button"
                    className="text-white py-2 px-4 rounded"
                    style={{ backgroundColor: colorTheme.primary }}
                    onClick={fetchDataFromURL}
                    disabled={loading}
                >
                    {loading ? "Searching..." : "Search"}
                </button>
            </div>
            {error && <p className="text-red-500 mt-2">{error}</p>}
        </div>
    );
};

export default SearchByURL;