import React, { useEffect, useState } from 'react';
import { FaEye, FaEdit, FaTrash, FaFlag } from 'react-icons/fa';
import { useNavigate } from 'react-router-dom';
import { colorTheme } from '../../Utils/colortheme';
import { useDispatch, useSelector } from 'react-redux';
import { delete_article_service_auth, get_article_service_auth, update_article_status_service_auth } from '../../Services/ArticleService';
import { asyncStatus } from '../../Utils/asyncStatus';
import { Oval } from 'react-loader-spinner';
import { setArticleIdleStatus } from '../../Store/slices/Article_slice';

const ArticlesOverviewTable = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const { get_article_data, get_article_status, delete_article_status, update_article_status_status, add_article_status } = useSelector((state) => state.article);

    const [searchTerm, setSearchTerm] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const [entriesPerPage, setEntriesPerPage] = useState(25);
    const [activeTab, setActiveTab] = useState('All');



    useEffect(() => {
        dispatch(get_article_service_auth());
        dispatch(setArticleIdleStatus());

    }, [dispatch, add_article_status]);

    useEffect(() => {
        if (delete_article_status === asyncStatus.SUCCEEDED) {
            dispatch(get_article_service_auth());
            dispatch(setArticleIdleStatus());
        }
    }, [delete_article_status]);

    useEffect(() => {
        if (update_article_status_status === asyncStatus.SUCCEEDED) {
            dispatch(get_article_service_auth());
            dispatch(setArticleIdleStatus());
        }
    }, [update_article_status_status]);

    // Filter articles by activeTab (status) and searchTerm
    const filteredArticles = get_article_data?.articles?.filter((entry) => {
        // Filter by status
        const statusMatch = activeTab === 'All' || entry.status === activeTab;

        // Ensure `name` exists before calling `.toLowerCase()`
        const title = entry?.publicData?.title?.name || "";
        const pmid = entry?.publicData?.pmid?.name || "";
        const doi = entry?.publicData?.doi?.name || "";

        // Convert searchTerm to lowercase safely
        const lowerSearchTerm = searchTerm ? searchTerm.toLowerCase() : "";

        // Filter by searchTerm (in title, PMID, DOI, or authors)
        const searchMatch =
            title.toLowerCase().includes(lowerSearchTerm) ||
            pmid.toLowerCase().includes(lowerSearchTerm) ||
            doi.toLowerCase().includes(lowerSearchTerm) ||
            entry?.publicData?.authors?.some(
                (author) => author?.name?.toLowerCase().includes(lowerSearchTerm)
            );

        return statusMatch && searchMatch;
    }) || [];

    // Pagination logic
    const indexOfLastEntry = currentPage * entriesPerPage;
    const indexOfFirstEntry = indexOfLastEntry - entriesPerPage;
    const currentEntries = filteredArticles.slice(indexOfFirstEntry, indexOfLastEntry);

    const paginate = (pageNumber) => setCurrentPage(pageNumber);

    const handleEntriesPerPageChange = (e) => {
        const value = e.target.value;

        if (value === "all") {
            setEntriesPerPage(1000000000000); // Set a high value to represent "All"
        } else {
            setEntriesPerPage(Number(value)); // Convert other values to a number
        }

        setCurrentPage(1); // Reset to the first page when changing entries per page
    };

    const handlePreview = (entry) => {
        navigate("/article-preview", { state: { articleToPreview: entry } });
    };

    const handleEdit = (entry) => {
        navigate("/main-form", { state: { articleToEdit: entry } });
    };

    const handleSpecialAction = (entry) => {
        navigate("/main-form", { 
          state: { 
            articleToEdit: entry,
            isSpecialAction: true
          }
        });
      };


    const handleDelete = (id) => {
        if (window.confirm("Are you sure you want to delete this article?")) {
            dispatch(delete_article_service_auth(id));
        }
    };


    const handleStatusChange = (id, newStatus) => {
        dispatch(update_article_status_service_auth({ id: id, status: newStatus }));
        console.log("status", { id: id, status: newStatus });

    };

    useEffect(() => {
        if (add_article_status === asyncStatus.SUCCEEDED) {
            dispatch(setArticleIdleStatus());
        }
    }, [add_article_status])


    // Tabs for filtering articles by status
    const tabs = ['All', 'Unverified', 'In Review', 'Verified', 'Draft'];

    if (get_article_status === asyncStatus.LOADING) {
        return (
            <div className="flex flex-col items-center justify-center py-20">
                <Oval secondaryColor='lightblue' color={colorTheme.primary} height={50} width={50} />
                <p className="mt-4 text-lg font-medium text-gray-600">Loading articles, please wait...</p>
            </div>
        );
    }

    return (
        <div className="container mx-auto p-6">

            <div className="flex justify-between items-center mb-4">
                <h1 className="text-2xl font-bold">Articles Overview</h1>
                <button
                    onClick={() => navigate("/main-form")}
                    className="text-white py-2 px-4 rounded"
                    style={{ backgroundColor: colorTheme.primary }}
                >
                    Add New
                </button>
            </div>

            {/* Tabs for filtering articles by status */}
            <div className="flex mb-4 space-x-4">
                {tabs.map(tab => (
                    <button
                        key={tab}
                        onClick={() => setActiveTab(tab)}
                        className={`py-2 px-4 rounded`}
                        style={{
                            backgroundColor: activeTab === tab ? colorTheme.primary : "white",
                            color: activeTab === tab ? "white" : "black",
                            border: activeTab === tab ? "none" : "1px solid #ccc",
                        }}
                    >
                        {tab}
                    </button>
                ))}
            </div>

            {/* Search and Pagination Controls */}
            <div className="flex justify-between items-center mb-4">
                <div>
                    <label>Show</label>
                    <select
                        className="mx-2 border p-2 rounded"
                        onChange={handleEntriesPerPageChange}
                        value={entriesPerPage === 1000000000000 ? "all" : entriesPerPage} // Map special value back to "all"
                    >
                        <option value="25">25</option>
                        <option value="50">50</option>
                        <option value="100">100</option>
                        <option value="500">500</option>
                        <option value="all">All</option>
                    </select>
                    <span>entries per page</span>
                </div>
                <input
                    type="text"
                    placeholder="Search by Title or ..."
                    className="border p-2 rounded"
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>

            {/* Articles Table */}

            <div className="overflow-x-auto">
                <table className="table-auto w-full text-left border-collapse border border-gray-200">
                    <thead>
                        <tr className="bg-gray-100">
                            <th className="border p-2">Article Title</th>
                            <th className="border p-2">Authors</th>
                            <th className="border p-2">Country</th>
                            <th className="border p-2">PMID</th>
                            <th className="border p-2">DOI</th>
                            <th className="border p-2">Status</th>
                            <th className="border p-2">Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {currentEntries.map((entry, index) => {
                            return (
                                <tr key={index} className="hover:bg-gray-50">
                                    {/* Title Handling */}
                                    <td className="border p-2">
                                        {entry?.publicData?.title?.name || "N/A"}
                                    </td>

                                    {/* Authors Handling */}
                                    <td className="border p-2">
                                        {entry?.publicData?.authors && entry.publicData.authors.length > 0 ? (
                                            entry.publicData.authors.map((author, idx) => (
                                                <span key={idx}>
                                                    {author.name}
                                                    {idx < entry.publicData.authors.length - 1 && ", "}
                                                </span>
                                            ))
                                        ) : (
                                            "N/A"
                                        )}
                                    </td>

                                    {/* Country Handling */}
                                    <td className="border p-2">
                                        {entry?.publicData?.country && entry.publicData.country.length > 0 ? (
                                            entry.publicData.country.map((c, idx) => (
                                                <span key={idx}>
                                                    {c.name}
                                                    {idx < entry.publicData.country.length - 1 && ", "}
                                                </span>
                                            ))
                                        ) : (
                                            "N/A"
                                        )}
                                    </td>

                                    {/* PMID Handling */}
                                    <td className="border p-2">{entry.publicData?.pmid?.name || "N/A"}</td>

                                    {/* DOI Handling */}
                                    <td className="border p-2">
                                        {entry.publicData?.doi?.name ? (
                                            <a
                                                href={`https://${entry.publicData.doi.name}`}
                                                style={{ color: colorTheme.primary, textDecoration: "underline" }}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                            >
                                                {entry.publicData.doi.name}
                                            </a>
                                        ) : (
                                            "N/A"
                                        )}
                                    </td>

                                    {/* Status Dropdown */}
                                    <td className="border p-2">
                                        <select
                                            className="border p-1 rounded"
                                            value={entry.status || "N/A"}
                                            onChange={(e) => handleStatusChange(entry.id, e.target.value)}
                                            disabled={entry.status === "Verified"} // Disable if Verified
                                        >
                                            <option value="Unverified">Unverified</option>
                                            <option value="In Review">In Review</option>
                                            <option value="Verified">Verified</option>
                                            <option value="Draft">Draft</option>
                                        </select>
                                    </td>

                                    {/* Actions */}
                                    <td className="border p-2">
                                        <div className="flex items-center space-x-4">
                                            {/* View */}
                                            {/* <FaEye
                                                color={colorTheme.primary}
                                                size={25}
                                                className="cursor-pointer"
                                                onClick={() => handlePreview(entry)}
                                            /> */}

                                            {/* Edit */}
                                            <FaEdit
                                                color={entry.status === "Verified" ? "gray" : colorTheme.primary}
                                                size={25}
                                                className={`cursor-pointer ${entry.status === "Verified" ? "cursor-not-allowed" : ""}`}
                                                onClick={() => entry.status !== "Verified" && handleEdit(entry)}
                                            />
                                            {/*handleSpecialAction  */}
                                            <FaFlag
                                                color={entry.status === "Verified" ? "gray" : colorTheme.primary}
                                                size={20}
                                                className={`cursor-pointer`}
                                                onClick={() => handleSpecialAction(entry)}
                                            />

                                            {/* Delete */}
                                            <FaTrash
                                                color={entry.status === "Verified" ? "gray" : "red"}
                                                size={20}
                                                className={`cursor-pointer ${entry.status === "Verified" ? "cursor-not-allowed" : ""}`}
                                                onClick={() => entry.status !== "Verified" && handleDelete(entry.id)}
                                            />
                                        </div>
                                    </td>
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>


            {/* Pagination Controls */}
            <div className="flex justify-between items-center mt-4">
                <span>
                    Showing {indexOfFirstEntry + 1} to {Math.min(indexOfLastEntry, filteredArticles.length)} of {filteredArticles.length} entries
                </span>
                <div className="flex gap-2">
                    {Array.from({ length: Math.ceil(filteredArticles.length / entriesPerPage) }, (_, index) => (
                        <button
                            key={index}
                            onClick={() => paginate(index + 1)}
                            className={`px-3 py-1 border ${currentPage === index + 1 ? 'bg-blue-500 text-white' : 'bg-white text-black'}`}
                            style={{
                                backgroundColor: currentPage === index + 1 ? colorTheme.primary : "white",
                                color: currentPage === index + 1 ? "white" : colorTheme.primary,
                            }}
                        >
                            {index + 1}
                        </button>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default ArticlesOverviewTable;