import React, { useState, useEffect } from "react";
import { Table, Input, Button, Modal, Form, notification } from "antd";
import { PlusOutlined, EditOutlined, DeleteOutlined } from "@ant-design/icons";
import { useDispatch, useSelector } from "react-redux";
import { apiHandle } from "../../../Config/ApiHandle/apiHandle";
import BackButton from "../../../Component/BackBtn/BackButton";
import { get_specie_service_auth ,add_specie_service_auth} from "../../../Services/SpecieService";

const Species = () => {
  const dispatch = useDispatch();
  const { get_specie_data } = useSelector((state) => state.species);

  const [filteredSpecies, setFilteredSpecies] = useState([]);
  const [searchValue, setSearchValue] = useState("");
  const [isModalVisible, setIsModalVisible] = useState(false);
  const [editingSpecies, setEditingSpecies] = useState(null);
  const [form] = Form.useForm();

  useEffect(() => {
    // Fetch species on component mount
    dispatch(get_specie_service_auth());
  }, [dispatch]);

  useEffect(() => {
    // Update filtered species whenever species data is fetched
    if (get_specie_data?.species) {
      setFilteredSpecies(get_specie_data.species);
    }
  }, [get_specie_data]);

  // Search functionality
  const handleSearch = (value) => {
    setSearchValue(value);
    const filtered = get_specie_data?.species.filter((species) =>
      species.name.toLowerCase().includes(value.toLowerCase())
    );
    setFilteredSpecies(filtered);
  };

  // Add or Edit species
  const handleModalOk = async () => {
    try {
      const values = await form.validateFields();
      if (editingSpecies) {
        // Edit logic
        await apiHandle.post(`/edit-specie/${editingSpecies.id}`, {
          name: values.name,
        });
        notification.success({ message: "Species updated successfully!" });

        // Update local state for real-time updates
        setFilteredSpecies((prev) =>
          prev.map((species) =>
            species.id === editingSpecies.id ? { ...species, name: values.name } : species
          )
        );
      } else {
        // Add species
        const obj = { name: values.name };
        const response = await dispatch(add_specie_service_auth(obj));

        if (response?.payload?.id) {
          // Add new species to local state
          setFilteredSpecies((prev) => [
            ...prev,
            { id: response.payload.id, name: obj.name },
          ]);
          // notification.success({ message: "Species added successfully!" });
        }
      }
      dispatch(get_specie_service_auth());
      setIsModalVisible(false);
      setEditingSpecies(null);
      form.resetFields();
    } catch (error) {
      console.error("Error while adding/editing species:", error);
      notification.error({ message: "Failed to add or update species." });
    }
  };

  // Show modal for adding or editing
  const handleAddEdit = (species = null) => {
    setEditingSpecies(species);
    setIsModalVisible(true);
    if (species) {
      form.setFieldsValue({ name: species.name });
    } else {
      form.resetFields();
    }
  };

  // Delete species
  const handleDelete = async (id) => {
    try {
      await apiHandle.delete(`/delete-species/${id}`);
      notification.success({ message: "Species deleted successfully!" });

      // Update local state for real-time updates
      setFilteredSpecies((prev) => prev.filter((species) => species.id !== id));
    } catch (error) {
      console.error("Error while deleting species:", error);
      notification.error({ message: "Failed to delete species." });
    }
  };

  // Table columns
  const columns = [
    {
      title: "Species Name",
      dataIndex: "name",
      key: "name",
    },
    {
      title: "Actions",
      key: "actions",
      render: (_, record) => (
        <div style={{ display: "flex", gap: "10px" }}>
          <Button
            style={{
              backgroundColor: "#004c78",
              color: "white",
            }}
            icon={<EditOutlined />}
            onClick={() => handleAddEdit(record)}
          >
            Edit
          </Button>
          <Button
            style={{
              backgroundColor: "#fff1f0",
              color: "#cf1322",
              borderColor: "#ffa39e",
            }}
            icon={<DeleteOutlined />}
            onClick={() => handleDelete(record.id)}
          >
            Delete
          </Button>
        </div>
      ),
    },
  ];

  return (
    <div className="container mx-auto p-6">
      <div className="flex space-x-5 items-center mb-6">
        <BackButton path={"/DataManager"} />
        <h1 className="text-2xl font-bold">Species Management</h1>
      </div>
      <div className="flex justify-between items-center mb-3">
        <Input.Search
          placeholder="Search species"
          value={searchValue}
          onChange={(e) => handleSearch(e.target.value)}
          style={{ width: "300px" }}
        />
        <Button
          style={{
            marginTop: "10px",
            backgroundColor: "#004c78",
            color: "white",
          }}
          icon={<PlusOutlined />}
          onClick={() => handleAddEdit()}
        >
          Add Species
        </Button>
      </div>
      <Table
        columns={columns}
        dataSource={filteredSpecies}
        rowKey="id"
        pagination={{ pageSize: 15 }}
      />

      {/* Modal for Adding/Editing */}
      <Modal
        title={editingSpecies ? "Edit Species" : "Add Species"}
        visible={isModalVisible}
        onOk={handleModalOk}
        onCancel={() => {
          setIsModalVisible(false);
          setEditingSpecies(null);
          form.resetFields();
        }}
        okText={editingSpecies ? "Update" : "Add"}
        okButtonProps={{
          style: { backgroundColor: "#004c78", borderColor: "#004c78" },
        }}
      >
        <Form form={form} layout="vertical">
          <Form.Item
            label="Species Name"
            name="name"
            rules={[{ required: true, message: "Please enter species name" }]}
          >
            <Input />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

export default Species;
