import React, { useEffect, useState } from 'react';
import Modal from 'react-modal';
import { colorTheme } from '../../Utils/colortheme';
import { useDispatch, useSelector } from 'react-redux';
import { add_user_service_auth, get_user_service_auth, edit_user_service_auth } from '../../Services/UserManagement';
import { asyncStatus } from '../../Utils/asyncStatus';
import { ClipLoader } from 'react-spinners';
import { FaEdit } from 'react-icons/fa';
import BackButton from '../BackBtn/BackButton';

const customStyles = {
    content: {
        top: '50%',
        left: '50%',
        right: 'auto',
        bottom: 'auto',
        marginRight: '-50%',
        transform: 'translate(-50%, -50%)',
        backgroundColor: '#fff',
        borderRadius: '10px',
        padding: '20px',
        boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)',
        width: '400px', // Adjusted width
    },
    overlay: {
        backgroundColor: 'rgba(0, 0, 0, 0.5)',
    },
};

Modal.setAppElement('#root');

const UserManager = () => {
    const dispatch = useDispatch();
    const { user, getUserStatus, addUserStatus, editUserStatus } = useSelector((state) => state.user);

    const [userList, setUserList] = useState([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const [entriesPerPage, setEntriesPerPage] = useState(5);
    const [newUser, setNewUser] = useState({ name: '', email: '', password: '', role: 'Admin', status: 'Active' });
    const [editingUser, setEditingUser] = useState(null);
    const [modalIsOpen, setModalIsOpen] = useState(false);
    const [isAdding, setIsAdding] = useState(false);
    const [isEditing, setIsEditing] = useState(false);

    useEffect(() => {
        dispatch(get_user_service_auth());
    }, [dispatch]);

    useEffect(() => {
        if (user?.users) {
            setUserList(user.users);
        }
    }, [user]);

    useEffect(() => {
        if (addUserStatus === asyncStatus.SUCCEEDED) {
            setUserList([...userList, { ...newUser, id: userList.length + 1 }]);
            closeModal();
            // setIsAdding(false);
        }
    }, [addUserStatus]);

    useEffect(() => {
        if (editUserStatus === asyncStatus.SUCCEEDED) {
            setUserList(
                userList.map((user) =>
                    user.id === editingUser.id
                        ? { ...user, name: newUser.name, email: newUser.email, role: newUser.role, status: newUser.status }
                        : user
                )
            );
            closeModal();
            setIsEditing(false);
        }
    }, [editUserStatus]);

    const filteredUsers = userList.filter(
        (user) =>
            user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
            user.email.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const indexOfLastEntry = currentPage * entriesPerPage;
    const indexOfFirstEntry = indexOfLastEntry - entriesPerPage;
    const currentUsers = filteredUsers.slice(indexOfFirstEntry, indexOfLastEntry);

    const paginate = (pageNumber) => setCurrentPage(pageNumber);

    const openModal = (user = null) => {
        if (user) {
            setEditingUser(user);
            setNewUser({ name: user.name, email: user.email, password: '', role: user.role, status: user.status });
        } else {
            setEditingUser(null);
            setNewUser({ name: '', email: '', password: '', role: 'Admin', status: 'Active' });
        }
        setModalIsOpen(true);
    };

    const closeModal = () => {
        setModalIsOpen(false);
        setNewUser({ name: '', email: '', password: '', role: 'Admin', status: 'Active' });
    };

    const handleAddUser = () => {
        if (newUser.name.trim() && newUser.email.trim() && newUser.password.trim()) {
            // setIsAdding(true);
            const newUserObject = {
                name: newUser.name,
                email: newUser.email,
                password: newUser.password,
                role: newUser.role,
                status: newUser.status,
            };
            dispatch(add_user_service_auth(newUserObject));
        }
    };

    const handleSaveUser = () => {
        if (newUser.name.trim() && newUser.email.trim()) {
            setIsEditing(true);
            const updatedUserObject = {
                id: editingUser.id,
                name: newUser.name,
                email: newUser.email,
                role: newUser.role,
                status: newUser.status,
            };
            dispatch(edit_user_service_auth({
                user_id: editingUser.id,
                update_data: updatedUserObject
            }));
        }
    };

    const handleDeleteUser = (id) => {
        setUserList(userList.filter((user) => user.id !== id));
    };

    return (
        <div className="container mx-auto p-6">
            <div className="flex space-x-5 items-center mb-6">
                <BackButton path={"/DataManager"} />  <h1 className="text-2xl font-bold">Researcher Management</h1>
            </div>

            <div className='flex justify-end'>
                <button
                    className="text-white py-2 px-4 rounded ml-4"
                    onClick={() => openModal()}
                    style={{
                        backgroundColor: colorTheme.primary
                    }}
                >
                    Add New Researcher
                </button>
            </div>

            <div className="flex justify-between items-center mb-4 mt-4">
                <div>
                    <label className="mr-2">Show</label>
                    <select
                        value={entriesPerPage}
                        onChange={(e) => setEntriesPerPage(Number(e.target.value))}
                        className="border px-2 py-1 rounded"
                    >
                        <option value={5}>5</option>
                        <option value={10}>10</option>
                        <option value={20}>20</option>
                    </select>
                    <span className="ml-2">entries per page</span>
                </div>
                <input
                    type="text"
                    className="border px-4 py-2 rounded"
                    placeholder="Search researcher..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    autoComplete="off"
                />
            </div>

            {getUserStatus === asyncStatus.LOADING ? (
                <div className="flex justify-center items-center h-64">
                    <ClipLoader size={50} color={"#004c78"} loading={true} />
                </div>
            ) : (
                <div>
                    <table className="table-auto w-full text-left border-collapse border border-gray-200">
                        <thead>
                            <tr className="bg-gray-100">
                                <th className="border p-2">#</th>
                                <th className="border p-2">Name</th>
                                <th className="border p-2">Email</th>
                                <th className="border p-2">Role</th>
                                <th className="border p-2">Status</th>
                                <th className="border p-2">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {currentUsers.map((user, index) => (
                                <tr key={user.id}>
                                    <td className="border p-2">{indexOfFirstEntry + index + 1}</td>
                                    <td className="border p-2">{user.name}</td>
                                    <td className="border p-2">{user.email}</td>
                                    <td className="border p-2">{user.role}</td>
                                    <td className="border p-2">{user.status}</td>
                                    <td className="border p-2">
                                        <div className="flex justify-center items-center">
                                            <button
                                                className="bg-[#004c78] text-white py-1 px-3 rounded"
                                                onClick={() => openModal(user)}
                                            >
                                                <FaEdit />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>

                    <div className="flex justify-between items-center mt-4">
                        <span>
                            Showing {indexOfFirstEntry + 1} to {Math.min(indexOfLastEntry, filteredUsers.length)} of {filteredUsers.length} entries
                        </span>
                        <div className="flex gap-2">
                            {Array.from({ length: Math.ceil(filteredUsers.length / entriesPerPage) }, (_, pageIndex) => (
                                <button
                                    key={pageIndex}
                                    onClick={() => paginate(pageIndex + 1)}
                                    className={`px-3 py-1 border`}
                                    style={{
                                        backgroundColor: currentPage === pageIndex + 1 ? colorTheme.primary : 'white',
                                        color: currentPage === pageIndex + 1 ? 'white' : colorTheme.primary,
                                    }}
                                >
                                    {pageIndex + 1}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            <Modal
                isOpen={modalIsOpen}
                onRequestClose={closeModal}
                style={customStyles}
                contentLabel="Add/Edit Researcher Modal"
            >
                <h2 className="text-xl font-bold mb-4">{editingUser ? 'Edit Researcher' : 'Add New Researcher'}</h2>
                <input
                    type="text"
                    className="border px-4 py-2 rounded w-full mb-2"
                    placeholder="Name"
                    value={newUser.name}
                    onChange={(e) => setNewUser({ ...newUser, name: e.target.value })}
                />
                <input
                    type="email"
                    className="border px-4 py-2 rounded w-full mb-2"
                    placeholder="Email"
                    value={newUser.email}
                    onChange={(e) => setNewUser({ ...newUser, email: e.target.value })}
                />
                {!editingUser && (
                    <input
                        type="password"
                        className="border px-4 py-2 rounded w-full mb-2"
                        placeholder="Password"
                        value={newUser.password}
                        onChange={(e) => setNewUser({ ...newUser, password: e.target.value })}
                    />
                )}
                <select
                    className="border px-4 py-2 rounded w-full mb-4"
                    value={newUser.role}
                    onChange={(e) => setNewUser({ ...newUser, role: e.target.value })}
                >
                    {/* <option value="Admin">Admin</option> */}
                    <option value="Researcher">Researcher</option>
                </select>
                <select
                    className="border px-4 py-2 rounded w-full mb-4"
                    value={newUser.status}
                    onChange={(e) => setNewUser({ ...newUser, status: e.target.value })}
                >
                    <option value="Active">Active</option>
                    <option value="In-Active">In-Active</option>
                </select>
                <div className="mt-4">
                    <button
                        className="text-white py-2 px-4 rounded mr-2"
                        onClick={editingUser ? handleSaveUser : handleAddUser}
                        style={{
                            backgroundColor: colorTheme.primary
                        }}
                        disabled={isAdding || isEditing}
                    >
                        {addUserStatus === asyncStatus.LOADING || editUserStatus === asyncStatus.LOADING ? 'Processing...' : editingUser ? 'Save' : 'Add'}
                    </button>
                    <button className="bg-gray-500 text-white py-2 px-4 rounded" onClick={closeModal} disabled={isAdding || isEditing}>
                        Cancel
                    </button>
                </div>
            </Modal>
        </div>
    );
};

export default UserManager;
