import React, { useState, useEffect } from "react";
import { Button, Table, Modal, Select, Input, notification, Tag } from "antd";
import { apiHandle } from "../../../Config/ApiHandle/apiHandle";
import BackButton from "../../../Component/BackBtn/BackButton";

const { Option } = Select;

const AuthorsHandling = () => {
  const [articles, setArticles] = useState([]);
  const [authorsLibrary, setAuthorsLibrary] = useState([]);
  const [selectedArticle, setSelectedArticle] = useState(null);
  const [updatedAuthors, setUpdatedAuthors] = useState([]);
  const [isModalVisible, setIsModalVisible] = useState(false);
  const [newParentAuthor, setNewParentAuthor] = useState("");
  const [loading, setLoading] = useState(false);
  const [assignModalVisible, setAssignModalVisible] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [searchFilter, setSearchFilter] = useState(""); // New state for the search filter

  useEffect(() => {
    const fetchArticles = async () => {
      try {
        const response = await apiHandle.get("get-article-authors"
        );
        const articlesWithDefaults = response.data.articles.map((article) => ({
          ...article,
          pmid: article.pmid || "N/A",
          mhid: article.mhid || "N/A",
          doi: article.doi || "N/A",
          authors: article.authors || [],
          authors_verified: article.authors_verified ? "Yes" : "No",
        }));
        setArticles(articlesWithDefaults);
      } catch (error) {
        console.error("Error fetching articles:", error);
      }
    };

    const fetchAuthorsLibrary = async () => {
      try {
        const response = await apiHandle.get("get-authors"
        );
        setAuthorsLibrary(response.data.authors);
      } catch (error) {
        console.error("Error fetching authors library:", error);
      }
    };

    fetchArticles();
    fetchAuthorsLibrary();
  }, []);

  const showModal = (article) => {
    setSelectedArticle(article);
    setUpdatedAuthors(article.authors);
    setIsModalVisible(true);
  };

  const handleAssignChange = (childName, parentId) => {
    setUpdatedAuthors((prev) =>
      prev.map((author) =>
        author.name === childName ? { ...author, parent_id: parentId } : author
      )
    );
  };

  const handleAddParentAuthor = async () => {
    if (!newParentAuthor.trim()) {
      notification.warning({ message: "Author name cannot be empty." });
      return;
    }

    setLoading(true);
    try {
      const payload = {
        name: newParentAuthor.trim(),
      };
      await apiHandle.post(
        "add-author",
        payload
      );
      notification.success({ message: "New parent author created successfully!" });
      setNewParentAuthor("");

      const response = await apiHandle.get(
        "get-authors"
      );
      setAuthorsLibrary(response.data.authors);
    } catch (error) {
      console.error("Error creating parent author:", error);
      notification.error({ message: "Failed to create parent author." });
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async () => {
    if (!selectedArticle) return;
    try {
      const payload = {
        mhid: selectedArticle.mhid,
        authors: updatedAuthors,
      };
      await apiHandle.post("verify-author",
        payload
      );
      notification.success({ message: "Authors updated successfully!" });
      setIsModalVisible(false);
      setSelectedArticle(null);
      setUpdatedAuthors([]);
    } catch (error) {
      console.error("Error submitting authors:", error);
      notification.error({ message: "Failed to update authors." });
    }
  };

  const openAssignModal = (record) => {
    setAssignModalVisible(record.name);
  };

  const filteredAuthors = authorsLibrary.filter((author) =>
    author.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleAssign = (childName, parentId) => {
    setUpdatedAuthors((prev) =>
      prev.map((author) =>
        author.name === childName ? { ...author, parent_id: parentId } : author
      )
    );
    notification.success({
      message: `Parent assigned successfully to ${childName}.`,
    });
    setAssignModalVisible(null);
  };

  const handleSearch = (value) => {
    setSearchFilter(value);
  };

  const filteredArticles = articles.filter((article) => {
    if (!searchFilter) return true;
    return (
      article.mhid.toLowerCase().includes(searchFilter.toLowerCase()) ||
      article.pmid.toLowerCase().includes(searchFilter.toLowerCase()) ||
      article.doi.toLowerCase().includes(searchFilter.toLowerCase())
    );
  });

  const articleColumns = [
    {
      title: "PMID",
      dataIndex: "pmid",
      key: "pmid",
    },
    {
      title: "MHID",
      dataIndex: "mhid",
      key: "mhid",
    },
    {
      title: "DOI",
      dataIndex: "doi",
      key: "doi",
      render: (text) =>
        text !== "N/A" ? (
          <a href={text} target="_blank" rel="noopener noreferrer">
            {text}
          </a>
        ) : (
          "N/A"
        ),
    },
    {
      title: "Authors Verified",
      dataIndex: "authors_verified",
      key: "authors_verified",
      render: (text) =>
        text === "Yes" ? (
          <Tag color="green">Verified</Tag>
        ) : (
          <Tag color="red">Not Verified</Tag>
        ),
    },
    {
      title: "Actions",
      key: "actions",
      render: (_, record) => (
        <Button
          style={{ backgroundColor: "#004c78", color: "white" }}
          onClick={() => showModal(record)}
        >
          Manage Authors
        </Button>
      ),
    },
  ];

  const authorColumns = [
    {
      title: "Name",
      dataIndex: "name",
      key: "name",
    },
    {
      title: "Parent Assigned",
      dataIndex: "parent_id",
      key: "parent_id",
      render: (parent_id) => {
        if (parent_id === 1) {
          return "Anonymous";
        }
        const parent = authorsLibrary.find((author) => author.id === parent_id);
        return parent ? parent.name : "Not Assigned";
      },
    },
    {
      title: "Assign",
      dataIndex: "parent_id",
      key: "parent_id",
      render: (parent_id, record) => (
        <>
          <Button
            style={{ backgroundColor: "#004c78", color: "white" }}
            onClick={() => openAssignModal(record)}
          >
            Assign
          </Button>
          <Modal
            title={`Assign Parent for: ${record.name}`}
            visible={assignModalVisible === record.name}
            onCancel={() => setAssignModalVisible(null)}
            footer={null}
          >
            <Input
              placeholder="Search Parent"
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <Table
              style={{ marginTop: "10px" }}
              columns={[
                {
                  title: "Name",
                  dataIndex: "name",
                  key: "name",
                  render: (_, author) => (
                    author.id === 1 ? (
                      <strong style={{ color: "#004c78" }}>Anonymous</strong>
                    ) : (
                      author.name
                    )
                  ),
                },
                {
                  title: "Action",
                  key: "action",
                  render: (_, author) => (
                    <Button
                      type="link"
                      onClick={() => handleAssign(record.name, author.id)}
                      className="text-[#004c78]"
                    >
                      Assign
                    </Button>
                  ),
                },
              ]}
              dataSource={[
                { id: 1, name: "Anonymous" }, // Add Anonymous as the first option
                ...filteredAuthors,
              ]}
              rowKey="id"
              pagination={{ pageSize: 7 }}
            />
          </Modal>
        </>
      ),
    },
  ];

  return (
    <div className="container mx-auto p-6">

      <div className="flex space-x-5 items-center mb-6">
        <BackButton path={"/DataManager"} />  <h1 className="text-2xl font-bold">Article Authors Management</h1>
      </div>
      <Input.Search
        placeholder="Search by MHID, PMID, or DOI"
        value={searchFilter}
        onChange={(e) => handleSearch(e.target.value)}
        style={{ marginBottom: "20px", width: "300px" }}
      />
      <Table
        columns={articleColumns}
        dataSource={filteredArticles}
        rowKey="mhid"
        pagination={{ pageSize: 20 }}
      />

      <Modal
        title={`Manage Authors for Article: ${selectedArticle?.mhid || "N/A"}`}
        visible={isModalVisible}
        onCancel={() => {
          setIsModalVisible(false);
          setSelectedArticle(null);
          setUpdatedAuthors([]);
        }}
        onOk={handleSubmit}
        okText="Submit"
        okButtonProps={{
          style: { backgroundColor: "#004c78", borderColor: "#004c78" },
          disabled: !updatedAuthors.length,
        }}
      >
        <Table
          columns={authorColumns}
          dataSource={updatedAuthors}
          rowKey="name"
          pagination={false}
          locale={{ emptyText: "No authors available" }}
        />
        <div className="mt-4">
          <Input
            placeholder="Add new parent author"
            value={newParentAuthor}
            onChange={(e) => setNewParentAuthor(e.target.value)}
          />
          <Button
            style={{
              marginTop: "10px",
              backgroundColor: "#004c78",
              color: "white",
            }}
            onClick={handleAddParentAuthor}
            loading={loading}
          >
            Add Parent Author
          </Button>
        </div>
      </Modal>
    </div>
  );
};

export default AuthorsHandling;


