import {
    Grid,
    Stack,
    Typography,
} from "@mui/material";
import React from "react";
import css from "./DashboardCard.module.css";
import blue_wave from "../../assets/blue_wave.png";
import orange_wave from "../../assets/orange_wave.png";
import { useSelector } from "react-redux";
import { colorTheme } from "../../Utils/colortheme";

const DashboardHome = ({ data }) => {
    const { user } = useSelector((state) => state.userAuth);

    // const jobsData = [
    //     {
    //         wave_img: blue_wave,
    //         count: data?.total_studies,
    //         title: "Number Of",
    //         second_txt: "Articles",
    //         backgroundClr: `linear-gradient(135deg, ${colorTheme.primary} 30%, #1E3A8A 100%)`,
    //     },
    //     {
    //         wave_img: orange_wave,
    //         count: data?.total_researcher,
    //         title: "Number Of",
    //         second_txt: "Researchers",
    //         backgroundClr: `linear-gradient(135deg, ${colorTheme.primary} 30%, #FF9800 100%)`,
    //     },
    //     {
    //         wave_img: orange_wave,
    //         count: data?.user_count,
    //         title: "Number Of",
    //         second_txt: "Users",
    //         backgroundClr: `linear-gradient(135deg, ${colorTheme.primary} 30%, #4CAF50 100%)`,
    //     },
    // ];

    const jobsData = [
        {
            wave_img: blue_wave,
            count: data?.total_studies,
            title: "Number Of",
            second_txt: "Articles",
            backgroundClr: `linear-gradient(135deg, #004C78 30%, #3498DB 100%)`, 
        },
        {
            wave_img: blue_wave,
            count: data?.total_researcher,
            title: "Number Of",
            second_txt: "Researchers",
            backgroundClr: `linear-gradient(135deg, #004C78 30%, #3498DB 100%)`, 
        },
        {
            wave_img: blue_wave,
            count: data?.user_count,
            title: "Number Of",
            second_txt: "Users",
            backgroundClr: `linear-gradient(135deg, #004C78 30%, #3498DB 100%)`, 
        },
    ];

    return (
        <Stack mt={5}>
            {/* Greeting Section */}
            <Stack
                gap={3}
                sx={{
                    animation: "fadeIn 1s ease-out, slideInFromTop 1s ease-out",
                }}
            >
                <Typography variant="caption" className={css.vendor_top_label_bl}>
                    Hi{" "}
                    <Typography
                        variant="caption"
                        className={`grediant_txt ${css.vendor_top_label_or}`}
                    >
                        {user?.name || "Admin"}{" "}
                        <Typography
                            variant="caption"
                            className={css.vendor_top_label_bl}
                        >
                            , Welcome to your{" "}
                            <Typography
                                variant="caption"
                                className={`grediant_txt ${css.vendor_top_label_or}`}
                            >
                                Dashboard
                            </Typography>
                        </Typography>
                    </Typography>
                </Typography>
                <hr color={"#D1D1D1"} style={{ marginBottom: 40 }} />
            </Stack>

            {/* Cards Section */}
            <Grid container spacing={3} alignItems={"stretch"}>
                {jobsData?.map(
                    ({ wave_img, title, count, backgroundClr, second_txt }, index) => (
                        <Grid item xl={4} lg={4} md={4} sm={4} xs={12} key={index}>
                            <Stack
                                className={`${css.avail_jobs} animate-card`}
                                justifyContent={"space-between"}
                                sx={{
                                    background: backgroundClr,
                                    height: "100%",
                                    borderRadius: "16px",
                                    overflow: "hidden",
                                    boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.15)",
                                    transition: "transform 0.4s ease, box-shadow 0.4s ease",
                                    "&:hover": {
                                        transform: "scale(1.08)",
                                        boxShadow: "0px 8px 20px rgba(0, 0, 0, 0.3)",
                                    },
                                }}
                            >
                                <Stack
                                    sx={{ padding: "24px", zIndex: 1 }}
                                    justifyContent={"space-between"}
                                >
                                    <Typography
                                        className={css.avail_count}
                                        sx={{
                                            color: "white",
                                            fontSize: "2.8rem",
                                            fontWeight: "bold",
                                        }}
                                        my={1}
                                    >
                                        {count || "0"}
                                    </Typography>
                                    <Typography
                                        variant="caption"
                                        className={css.avail_txt}
                                        my={1}
                                        sx={{
                                            color: "white",
                                            fontSize: "1.5rem",
                                        }}
                                    >
                                        {title}{" "}
                                        <Typography
                                            variant="caption"
                                            className={css.avail_job_txt}
                                            my={1}
                                            sx={{
                                                color: "white",
                                                fontSize: "1.5rem",
                                                fontWeight: "bold",
                                            }}
                                        >
                                            {second_txt || ""}
                                        </Typography>
                                    </Typography>
                                </Stack>
                                <img
                                    src={wave_img}
                                    alt=""
                                    style={{
                                        position: "absolute",
                                        bottom: 0,
                                        right: 0,
                                        width: "100%",
                                        height: "auto",
                                        opacity: 0.5,
                                    }}
                                />
                            </Stack>
                        </Grid>
                    )
                )}
            </Grid>
        </Stack>
    );
};

export default DashboardHome;
