import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { fetch_pmid_Article } from '../../Services/authentication';
import { colorTheme } from '../../Utils/colortheme';

const PMIDFormManager = () => {
    const dispatch = useDispatch();
    const { articleData, loading, error,
        Pmid_Article_Loading,
        Pmid_Article_Data,
        Pmid_Article_Error


    } = useSelector((state) => state.userAuth);

    const [query, setQuery] = useState('');
    const [searchTerm, setSearchTerm] = useState('');

    const handleSubmit = (e) => {
        e.preventDefault();
        if (query.trim()) {
            dispatch(fetch_pmid_Article(query));
            setSearchTerm(query);
        }
    };

    return (
        <div className="container mx-auto p-6">
            <h1 className="text-2xl font-bold mb-4">Search Article by PMID</h1>
            <form onSubmit={handleSubmit} className="mb-6">
                <input
                    type="text"
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    className="border px-4 py-2 rounded mr-4"
                    placeholder="Type PMID (e.g., 3932)..."
                    required
                />
                <button
                    type="submit"
                    className="text-white py-2 px-4 rounded"
                    style={{
                        backgroundColor:colorTheme.primary
                    }}
                >
                    Search
                </button>
            </form>

            {Pmid_Article_Loading && <p>Loading...</p>}

            {!Pmid_Article_Loading && error && <p className="text-red-500">{error}</p>}

            {!Pmid_Article_Loading && !error && Pmid_Article_Data && Pmid_Article_Data.length === 0 && (
                <p>No data found for this PMID: <span style={{color:'red',fontWeight:"bold"}}>{searchTerm}</span> </p>
            )}

            {!Pmid_Article_Loading && Pmid_Article_Data && Pmid_Article_Data.length > 0 && (
                <table className="min-w-full bg-white border-collapse border border-gray-200">
                    <thead>
                        <tr>
                            <th className="border p-2">DOI</th>
                            <th className="border p-2">Title</th>
                            <th className="border p-2">Author(s)</th>
                            <th className="border p-2">Abstract</th>
                        </tr>
                    </thead>
                    <tbody>
                        {Pmid_Article_Data.map((article, index) => (
                            <tr key={index}>
                                <td className="border p-2">
                                    <a
                                        href={`https://doi.org/${article.doi}`}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="text-blue-600"
                                    >
                                        {article.doi}
                                    </a>
                                </td>
                                <td className="border p-2">{article.title}</td>
                                <td className="border p-2">{article.authorString}</td>
                                <td className="border p-2">{article.abstractText}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            )}
        </div>
    );
};

export default PMIDFormManager;
