import React from "react";
import { Bar, Pie, Line, Doughnut } from "react-chartjs-2";
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    BarElement,
    LineElement,
    PointElement,
    Title,
    Tooltip,
    Legend,
    ArcElement,
} from "chart.js";
import { colorTheme } from "../Utils/colortheme";
import generateColors from "../Utils/generateColors";

ChartJS.register(
    CategoryScale,
    LinearScale,
    BarElement,
    LineElement,
    PointElement,
    Title,
    Tooltip,
    Legend,
    ArcElement
);

const DashboardCharts = ({ chartData }) => {

    console.log("chartData", chartData);


    // Transform TotalArticlesOverTime data for the line chart
    const lineChartData = {
        labels: chartData?.TotalArticlesOverTime?.map((item) => item.year),
        datasets: [
            {
                label: "Total Articles Over Time",
                data: chartData?.TotalArticlesOverTime?.map((item) => item.count),
                borderColor: colorTheme.primary,
                backgroundColor: "rgba(0, 123, 255, 0.2)",
                pointBackgroundColor: colorTheme.primary,
            },
        ],
    };

    // Transform Organs data for the horizontal bar chart
    const organsChartData = chartData?.Organs
        ? {
            labels: Object.keys(chartData.Organs),
            datasets: [
                {
                    label: "Organs",
                    data: Object.values(chartData.Organs),
                    backgroundColor: generateColors(Object.keys(chartData.Organs).length),
                },
            ],
        }
        : {
            labels: [],
            datasets: [
                {
                    label: "Organs",
                    data: [],
                    backgroundColor: [],
                },
            ],
        };

    // Transform Articles by Status data for the pie chart
    const pieChartData = chartData?.ArticlesbyStatus
        ? {
            labels: Object.keys(chartData.ArticlesbyStatus),
            datasets: [
                {
                    label: "Article Status",
                    data: Object.values(chartData.ArticlesbyStatus),
                    backgroundColor: generateColors(Object.keys(chartData.ArticlesbyStatus).length),
                },
            ],
        }
        : {
            labels: [],
            datasets: [
                {
                    label: "Article Status",
                    data: [],
                    backgroundColor: [],
                },
            ],
        };

    // Transform Research by Species data for the doughnut chart
    const speciesChartData = chartData?.ResearchbySpecies
        ? {
            labels: Object.keys(chartData.ResearchbySpecies),
            datasets: [
                {
                    label: "Research by Species",
                    data: Object.values(chartData.ResearchbySpecies),
                    backgroundColor: generateColors(Object.keys(chartData.ResearchbySpecies).length),
                },
            ],
        }
        : {
            labels: [],
            datasets: [
                {
                    label: "Research by Species",
                    data: [],
                    backgroundColor: [],
                },
            ],
        };

    // Transform Study Types data for the doughnut chart
    const studyTypeChartData = chartData?.StudyTypes
        ? {
            labels: Object.keys(chartData.StudyTypes),
            datasets: [
                {
                    label: "Study Types",
                    data: Object.values(chartData.StudyTypes),
                    backgroundColor: generateColors(Object.keys(chartData.StudyTypes).length),
                },
            ],
        }
        : {
            labels: [],
            datasets: [
                {
                    label: "Study Types",
                    data: [],
                    backgroundColor: [],
                },
            ],
        };

    // Transform Research by Topic data for the bar chart
    const topicBarChartData = chartData?.ResearchbyTopic
        ? {
            labels: Object.keys(chartData.ResearchbyTopic),
            datasets: [
                {
                    label: "Research by Topic",
                    data: Object.values(chartData.ResearchbyTopic),
                    backgroundColor: generateColors(Object.keys(chartData.ResearchbyTopic).length),
                },
            ],
        }
        : {
            labels: [],
            datasets: [
                {
                    label: "Research by Topic",
                    data: [],
                    backgroundColor: [],
                },
            ],
        };



    return (
        <div className="bg-white py-8">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {/* Articles by Status */}
                <div className="bg-white shadow-md rounded-lg flex">
                    <div className="w-2/3 p-4">
                        <h2 className="text-lg font-semibold mb-4">Articles by Status</h2>
                        <div className="h-72">
                            <Pie data={pieChartData} options={{ responsive: true }} />
                        </div>
                    </div>
                    <div className="w-1/3 flex items-center justify-center">
                        <ul className="text-sm">
                            {pieChartData.labels.map((label, index) => (
                                <li key={index} className="mb-2">
                                    <span
                                        className="inline-block w-3 h-3 mr-2"
                                        style={{
                                            backgroundColor:
                                                pieChartData.datasets[0].backgroundColor[index],
                                        }}
                                    ></span>
                                    {label}
                                </li>
                            ))}
                        </ul>
                    </div>
                </div>


                {/* Total Articles Over Time */}
                <div className="bg-white shadow-md rounded-lg p-4">
                    <h2 className="text-lg font-semibold mb-4">Total Articles Over Time</h2>
                    <div className="h-72">
                        <Line data={lineChartData} options={{ responsive: true }} />
                    </div>
                </div>


                {/* Research by Species */}
                <div className="bg-white shadow-md rounded-lg flex">
                    <div className="w-2/3 p-4">
                        <h2 className="text-lg font-semibold mb-4">Research by Species</h2>
                        <div className="h-72">
                            <Doughnut data={speciesChartData} options={{ responsive: true }} />
                        </div>
                    </div>
                    <div className="w-1/3 flex items-center justify-center">
                        <ul className="text-sm">
                            {speciesChartData.labels.map((label, index) => (
                                <li key={index} className="mb-2">
                                    <span
                                        className="inline-block w-3 h-3 mr-2"
                                        style={{
                                            backgroundColor:
                                                speciesChartData.datasets[0].backgroundColor[index],
                                        }}
                                    ></span>
                                    {label}
                                </li>
                            ))}
                        </ul>
                    </div>
                </div>


                {/* Study Types */}
                <div className="bg-white shadow-md rounded-lg flex overflow-hidden">
                    <div className="w-2/3 p-4">
                        <h2 className="text-lg font-semibold mb-4">Study Types</h2>
                        <div className="h-72">
                            <Doughnut data={studyTypeChartData} options={{ responsive: true }} />
                        </div>
                    </div>
                    <div className="w-1/3 flex items-center justify-center">
                        <ul className="text-sm">
                            {studyTypeChartData.labels.map((label, index) => (
                                <li
                                    key={index}
                                    className="mb-2 truncate"
                                    style={{
                                        maxWidth: "100%", // Ensures the label doesn't exceed the container width
                                        overflow: "hidden", // Hides overflowed text
                                        whiteSpace: "wrap", // Prevents text wrapping
                                        textOverflow: "ellipsis", // Adds ellipsis for truncated text
                                    }}
                                >
                                    <span
                                        className="inline-block w-3 h-3 mr-2"
                                        style={{
                                            backgroundColor:
                                                studyTypeChartData.datasets[0].backgroundColor[index],
                                        }}
                                    ></span>
                                    {label}
                                </li>
                            ))}
                        </ul>
                    </div>
                </div>


                {/* Research by Topic */}
                <div className="bg-white shadow-md rounded-lg p-4">
                    <h2 className="text-lg font-semibold mb-4">Research by Topic</h2>
                    <div className="h-72">
                        <Bar data={topicBarChartData} options={{ responsive: true }} />
                    </div>
                </div>

                {/* Organs */}
                <div className="bg-white shadow-md rounded-lg flex">
                    <div className="w-2/3 p-4">
                        <h2 className="text-lg font-semibold mb-4">Organs</h2>
                        <div className="h-72">
                            <Bar
                                data={organsChartData}
                                options={{
                                    indexAxis: "y", // Horizontal bar chart
                                    responsive: true,
                                    maintainAspectRatio: false,
                                }}
                            />
                        </div>
                    </div>
                    <div className="w-1/3 flex items-center justify-center">
                        <ul className="text-sm">
                            {organsChartData.labels.map((label, index) => (
                                <li key={index} className="mb-2">
                                    <span
                                        className="inline-block w-3 h-3 mr-2"
                                        style={{
                                            backgroundColor:
                                                organsChartData.datasets[0].backgroundColor[index],
                                        }}
                                    ></span>
                                    {label}
                                </li>
                            ))}
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default DashboardCharts;
